package org.sleepwell.app;
import android.app.*;import android.widget.*;import java.util.*;import java.util.function.*;

/** Draft-only configuration. No output, grant acquisition or scheduler work. */
final class AlarmSoundModesUi {
    static void render(Activity activity,LinearLayout body,Alarm alarm,Runnable redraw,Runnable back,Consumer<Supplier<Dialog>> open){
        Design.header(body,"Sound playback",back);Design.space(body,16);
        Design.item(body,"sound","Playback mode",alarm.soundModeInvalid?"Review sound mode":alarm.soundMode.title(),()->open.accept(()->SleepPicker.choices(activity,"Playback mode",new String[]{"Single sound","Silent","Playlist","Internet radio"},alarm.soundMode.kind.ordinal(),n->{if(n==3){open.accept(()->radio(activity,alarm,redraw));return;}alarm.soundMode=n==0?AlarmSoundMode.SINGLE:n==1?AlarmSoundMode.SILENT:alarm.soundMode.playlist()?alarm.soundMode:new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,List.of("daybreak","pulse"),false);alarm.soundModeInvalid=false;redraw.run();}))).setContentDescription("Playback mode");Design.line(body);
        if(alarm.soundMode.radio()){Design.space(body,18);Design.item(body,"link","Stream URL",AlarmRadioUrl.host(alarm.soundMode.radioUrl),()->open.accept(()->radio(activity,alarm,redraw)));Design.space(body,12);Design.text(body,"Internet required. Uses a direct HTTPS audio stream, without sign-in. If it cannot play or stalls for 8 seconds, Daybreak plays instead. Backup escalation stays bundled.",14,400,Design.MUTED);Design.space(body,12);Design.text(body,"No automatic network preview. Save the alarm to keep this source.",13,500,Design.BROWN);}
        else if(alarm.soundMode.silent()){Design.space(body,18);Design.text(body,"No alarm sound, including backup sound. Vibration, lights and challenges keep their own settings.",14,400,Design.MUTED);}
        else if(alarm.soundMode.playlist()){
            Design.toggle(body,"Shuffle order","One shuffled order for each alarm occurrence",alarm.soundMode.shuffle,on->{alarm.soundMode=alarm.soundMode.changed(alarm.soundMode.tracks,on);redraw.run();});Design.line(body);Design.space(body,12);
            for(int n=0;n<alarm.soundMode.tracks.size();n++){int index=n;String source=alarm.soundMode.tracks.get(n);LinearLayout row=Design.row(activity);row.addView(Design.text(activity,(n+1)+". "+alarm.soundMode.name(source),16,500,Design.INK),new LinearLayout.LayoutParams(0,-2,1));if(n>0)row.addView(Design.iconButton(activity,"up","Move sound "+(n+1)+" up",()->{List<String> tracks=new ArrayList<>(alarm.soundMode.tracks);Collections.swap(tracks,index,index-1);alarm.soundMode=alarm.soundMode.changed(tracks,alarm.soundMode.shuffle);redraw.run();}),new LinearLayout.LayoutParams(Design.dp(activity,48),Design.dp(activity,48)));if(alarm.soundMode.tracks.size()>2)row.addView(Design.iconButton(activity,"trash","Remove sound "+(n+1),()->{List<String> tracks=new ArrayList<>(alarm.soundMode.tracks);tracks.remove(index);alarm.soundMode=alarm.soundMode.changed(tracks,alarm.soundMode.shuffle);redraw.run();}),new LinearLayout.LayoutParams(Design.dp(activity,48),Design.dp(activity,48)));body.addView(row);Design.line(body);}
            List<String> choices=new ArrayList<>(List.of("daybreak","pulse","chime","system"));if(AlarmSoundMode.source(alarm.tone)&&alarm.tone.startsWith("content:"))choices.add(alarm.tone);choices.removeAll(alarm.soundMode.tracks);
            if(alarm.soundMode.tracks.size()<8&&!choices.isEmpty())Design.item(body,"plus","Add sound","Built-in or your selected imported audio",()->open.accept(()->SleepPicker.choices(activity,"Add sound",choices.stream().map(AlarmTones::name).toArray(String[]::new),-1,n->{alarm.soundMode=alarm.soundMode.add(choices.get(n),alarm.toneDisplayName);redraw.run();})));
            Design.space(body,12);Design.text(body,"Each sound finishes before the next. The list repeats. To add a file, import it in Alarm sound, then add it here.",13,400,Design.MUTED);
        }else{Design.space(body,18);Design.text(body,"Repeats your selected alarm sound.",14,400,Design.MUTED);}
        if(alarm.soundModeInvalid)Design.text(body,"Saved playback settings could not be read. Choose a mode before saving.",13,500,0xffa93919);
        Design.space(body,16);Design.fixedAction(body,"Use playback settings",back);
    }
    private static Dialog radio(Activity activity,Alarm alarm,Runnable redraw){Dialog dialog=new Dialog(activity);dialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);LinearLayout root=Design.col(activity);Design.pad(root,22,20);root.setBackground(Design.shape(activity,Design.CREAM,22));Design.text(root,"Internet radio",22,600,Design.INK);Design.space(root,12);Design.text(root,"Requires Internet and a direct public HTTPS audio stream. No Spotify, sign-in pages or URLs containing credentials. Daybreak fallback is always kept.",14,400,Design.MUTED);Design.space(root,14);EditText url=new EditText(activity);url.setText(alarm.soundMode.radio()?alarm.soundMode.radioUrl:"");url.setHint("https://radio.example/live.mp3");url.setContentDescription("Radio stream URL");url.setSingleLine(true);url.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI|android.text.InputType.TYPE_TEXT_FLAG_NO_SUGGESTIONS);url.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(2048)});url.setTextSize(16);url.setTypeface(Design.font(activity,400));url.setTextColor(Design.INK);Design.pad(url,12,14);url.setBackground(Design.outline(activity,Design.SOFT,Design.LINE,12));root.addView(url,new LinearLayout.LayoutParams(-1,-2));Design.space(root,10);TextView error=Design.text(root,"",13,500,0xffa93919);error.setVisibility(android.view.View.GONE);Design.button(root,"Use radio source",true,()->{try{AlarmSoundMode mode=AlarmSoundMode.radio(url.getText().toString().strip());alarm.soundMode=mode;alarm.soundModeInvalid=false;dialog.dismiss();redraw.run();}catch(IllegalArgumentException invalid){error.setText(invalid.getMessage());error.setVisibility(android.view.View.VISIBLE);error.post(()->error.requestRectangleOnScreen(new android.graphics.Rect(0,0,error.getWidth(),error.getHeight()),true));}});Design.button(root,"Cancel",false,dialog::dismiss);ScrollView scroll=new ScrollView(activity);scroll.addView(root);dialog.setContentView(scroll);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(activity.getResources().getDisplayMetrics().widthPixels-Design.dp(activity,32),Design.dp(activity,430)),-2);dialog.getWindow().setSoftInputMode(android.view.WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);return dialog;}
}
